export const DeliveryMetricAggregateSchema = z.union([z.object({
        scope: z.literal("standard"),
        metric_id: AvailableMetricSchema,
        qualifier: CanonicalMetricQualifierSchema.optional(),
        value: z.number(),
        measurable_impressions: z.number().min(0).optional(),
        viewable_impressions: z.number().min(0).optional(),
        impressions: z.number().min(0).optional(),
        completed_views: z.number().min(0).optional(),
        spend: z.number().min(0).optional(),
        conversions: z.number().min(0).optional(),
        conversion_value: z.number().min(0).optional(),
        clicks: z.number().min(0).optional()
    }).passthrough(), z.object({
        scope: z.literal("vendor"),
        vendor: BrandReferenceSchema,
        metric_id: VendorMetricIDSchema,
        qualifier: CanonicalMetricQualifierSchema.optional(),
        value: z.number(),
        measurable_impressions: z.number().min(0).optional()
    }).passthrough()]).superRefine((row, ctx) => {
    if (row.scope !== "standard") return;
    const requiredComponents: Record<string, string[]> = {
        viewable_rate: ["measurable_impressions", "viewable_impressions"],
        completion_rate: ["impressions", "completed_views"],
        cost_per_acquisition: ["spend", "conversions"],
        roas: ["spend", "conversion_value"]
    };
    for (const field of requiredComponents[row.metric_id] ?? []) {
        if ((row as unknown as Record<string, unknown>)[field] === undefined) {
            ctx.addIssue({ code: "custom", path: [field], message: `${field} is required for ${row.metric_id}` });
        }
    }
});

